def describe(name, ftype, comment):
    if comment: return comment
    if name in G: return G[name]
    if name.endswith("_id"): return "Идентификатор: " + name[:-3].replace("_", " ")
    if name.endswith("_at"): return "Момент времени: " + name[:-3].replace("_", " ")
    return name.replace("_", " ").capitalize()
